INSERT INTO vi_business_base (company_id, code, name, kind, capital_basis, driver1_label, driver1_unit, driver2_label, driver2_unit, driver_scale, boundary, sort) VALUES ((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'B1', '建筑与地产（合并）', '经营', '股权', NULL, NULL, NULL, NULL, NULL, '房建、基建、勘察设计与地产开发（中海地产）合并为一块：旧模型只有集团口径的新签合同与收入转化率，还没有分板块的收入、利润率和资本。股权口径：现金、带息负债、少数股东都在资本与利润里，不进资产负债桥。', 1) ON CONFLICT (company_id, code) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, capital_basis = EXCLUDED.capital_basis, driver1_label = EXCLUDED.driver1_label, driver1_unit = EXCLUDED.driver1_unit, driver2_label = EXCLUDED.driver2_label, driver2_unit = EXCLUDED.driver2_unit, driver_scale = EXCLUDED.driver_scale, boundary = EXCLUDED.boundary, sort = EXCLUDED.sort;
INSERT INTO vi_line_base (business_id, code, name, kind, basis, sort, driver_scale, driver1_label, driver1_unit, driver2_label, driver2_unit) VALUES ((SELECT id FROM vi_business_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND code = 'B1'), 'R1', '工程与地产收入', '收入', '驱动', 1, 1, '新签合同总额（建筑新签＋地产合约销售）', '亿元', '收入转化率（营业收入÷新签合同总额）', '比率（0.46＝每 1 元新签对应当年 0.46 元收入）');
INSERT INTO vi_line_base (business_id, code, name, kind, basis, sort, note, driver_scale) VALUES ((SELECT id FROM vi_business_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND code = 'B1'), 'C1', '付现成本（占收入）', '成本', '收入比例', 11, '付现成本÷收入', 1);
INSERT INTO vi_line_base (business_id, code, name, kind, basis, sort) VALUES ((SELECT id FROM vi_business_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND code = 'B1'), 'C2', '折旧摊销', '成本', '金额', 12);
