INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'J-IC', '期初投入资本与资产负债桥（统一估值引擎）', '已形成建议', '2026-06-30 归母权益 5,039.5 亿元，减去资产负债桥里按账面计的项目净额 -90.0 亿元（永续债（归母权益中的其他权益工具）；负数＝负债多于资产），得到股权口径的期初资本（归母净资产口径） 5,129.5 亿元。业务资本和资产负债桥合起来正好是报表的归母权益，没有重复或遗漏（自动检查 V09 对账）。', '投入资本是资产价值（未填重置成本时）和 ROIC 的分母；资本增加从自由现金流里扣。', '估值假设·期初投入资本；资产负债桥 N 项', '新的半年报或年报出来后，按同一口径更新截至日与金额。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'J-NORM', '正常化经营利润率（盈利能力价值用）', '已形成建议', '2016—2025 年 10 年的平均税前利润率 5.0%（利润总额÷营业收入，股权口径：利息后），代表一个完整周期的中枢。', '盈利能力价值＝第一个完整年度收入×正常化经营利润率×(1−税率)÷门槛；只影响“三层价值”的中间一层，不影响全价值。', '估值假设·正常化经营利润率', '行业格局或公司成本结构发生持久变化（不是周期波动）时改用新的中枢。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'J-PROB', '情景概率 25% / 50% / 25%（待确认）', '已形成建议', '还没有逐一论证情景概率，先按悲观 25%、基准 50%、乐观 25% 给出概率加权价值；要改时写清楚为什么某一情景更可能。', '只影响概率加权每股价值，不影响各情景本身。', '情景·情景概率', '有证据表明某一情景的可能性明显更高或更低。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'J-BASIS', '用股权口径估值：便宜的负债是价值的一部分', '已形成建议', '带息负债约 9,500 亿元、平均成本约 2%，少数股东权益 3,369 亿元。企业口径按 6% 门槛折现经营现金流、再按账面扣负债，等于把 2% 的负债当成 6% 的成本，基准情景每股价值约为 0（2026-11-08 试算：悲观 −5.77、基准 −0.05、乐观 4.07 元，隐含回报 5.2%）。股权口径直接看归母利润与归母净资产，负债的低成本留在利润里，和旧股息贴现模型一致。', '成本线含利息；税后利润×归母比例＝归母净利；资本＝归母净资产；净投资＝留存利润；自由现金流＝股息。ROE 代替 ROIC。', '业务·资本口径', '负债大幅下降、或融资成本接近门槛时，改回企业口径。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
INSERT INTO vi_sotp_item_base (model_id, scenario_id, business_id, code, name, kind, treatment, valuation_method, amount, haircut, as_of, basis) VALUES ((SELECT id FROM vi_model_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND status = '当前'), NULL, NULL, 'N1', '永续债（归母权益中的其他权益工具）', '其他调整', '单独计价', '账面价值', -90, 0, '2026-06-30', '永续债 90.0（亿元）。计在归母权益里，但属于债权人，扣除。');
